const outDir = resolve(argv.shift() ?? "docs/rpc-samples");
const opt = (name, dflt) => {
	const i = argv.indexOf(name);
	return i === -1 ? dflt : argv.splice(i, 2)[1];
};
const cwd = resolve(opt("--cwd", process.cwd()));
