	stdio: ["pipe", "pipe", "pipe"],
	env: process.env,
});

const frames = [];
const sent = [];
let stderr = "";
let buf = "";
const waiters = new Set();

child.stderr.setEncoding("utf8");
child.stderr.on("data", (d) => {
	stderr += d;
});

child.stdout.setEncoding("utf8");
