			waiters.delete(w);
			rej(new Error(`timeout waiting for ${label}`));
		}, timeout);
		waiters.add(w);
	});
}

async function command(type, payload = {}) {
	const id = nextId();
	const from = frames.length;
	send({ id, type, ...payload });
	const res = await waitFor((f, i) => f.type === "response" && f.id === id && i >= from - 1, {
